(101, 'd0000000-0000-0000-0000-000000000000', 2, 'Corredores Verdes CDMX', 'Iniciativa para conectar los principales parques de la Ciudad de México mediante corredores biológicos...', 11, 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=800&q=80', 35, 'Activo', '{Voluntarios, Alianzas Gubernamentales}', true),
(102, 'd0000000-0000-0000-0000-000000000000', 2, 'Sensores de Calidad de Aire Low-Cost', 'Desarrollo de una red de sensores IoT de bajo costo...', 3, 'https://images.unsplash.com/photo-1581093458791-9f3c3900df4b?auto=format&fit=crop&w=800&q=80', 78, 'Fase de Prueba', '{Inversión Semilla, Desarrolladores}', false),
(103, 'd1111111-1111-1111-1111-111111111111', 1, 'Huertos Urbanos Verticales', 'Sistema modular de agricultura vertical para espacios reducidos en apartamentos de Bogotá.', 2, 'https://images.unsplash.com/photo-1530836369250-ef72a3f5cda8?auto=format&fit=crop&w=800&q=80', 15, 'Planeación', '{Materiales, Arquitectos}', false)
INSERT INTO public.posts (id, user_id, location, sdg_ids, title, content, images, likes_count, comments_count) VALUES
(101, 'd0000000-0000-0000-0000-000000000000', 'Ciudad de México, MX', '{11}', 'Avance en la Ley de Corredores Verdes', 'Hoy tuvimos una reunión clave con la secretaría de medio ambiente. La propuesta para interconectar los parques urbanos ha pasado a la siguiente fase de revisión.', '{"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=800&q=80"}', 245, 42),
(102, 'd4444444-4444-4444-4444-444444444444', 'Océano Pacífico', '{14}', 'System 03: Despliegue Exitoso', 'Nuestro nuevo sistema de recolección ha sido desplegado exitosamente en el Gran Parche de Basura del Pacífico.', '{"https://images.unsplash.com/photo-1484291470158-b8f8d608850d?auto=format&fit=crop&w=800&q=80", "https://images.unsplash.com/photo-1621451537084-482c73073a0f?auto=format&fit=crop&w=800&q=80"}', 8902, 315),
(103, 'd1111111-1111-1111-1111-111111111111', 'Bogotá, Colombia', '{2}', 'Primera cosecha del Huerto Comunitario San Felipe', 'Lo que antes era un lote baldío lleno de escombros, hoy nos dio nuestra primera caja de tomates y lechugas orgánicas.', '{"https://images.unsplash.com/photo-1530836369250-ef72a3f5cda8?auto=format&fit=crop&w=800&q=80"}', 189, 24),
(104, 'd2222222-2222-2222-2222-222222222222', 'Oaxaca, México', '{7}', 'Energía para la Escuela "El Porvenir"', 'Terminamos la instalación de 12 paneles solares. Por primera vez, esta escuela rural tendrá electricidad constante.', '{"https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=800&q=80"}', 456, 56),
(105, 'd3333333-3333-3333-3333-333333333333', 'Lima, Perú', '{4}', 'Becas de Programación para Mujeres', 'Abrimos la convocatoria para nuestro bootcamp intensivo de desarrollo web 50 becas disponibles.', '{}', 320, 89),
(106, 'd7777777-7777-7777-7777-777777777777', 'Medellín, Colombia', '{12}', '¿Ladrillos de plástico reciclado?', 'Estamos prototipando muros de carga utilizando 100% plástico reciclado post-consumo.', '{"https://images.unsplash.com/photo-1518005020951-ecc8e5613b5d?auto=format&fit=crop&w=800&q=80", "https://images.unsplash.com/photo-1589829545856-d10d557cf95f?auto=format&fit=crop&w=800&q=80"}', 670, 95),
(107, 'd5555555-5555-5555-5555-555555555555', 'São Paulo, Brasil', '{5}', 'Marcha por la Igualdad Salarial', 'Ayer las calles se llenaron de voces exigiendo lo justo: a igual trabajo, igual salario.', '{"https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?auto=format&fit=crop&w=800&q=80"}', 1200, 45),
(108, 'd6666666-6666-6666-6666-666666666666', 'Esmeraldas, Ecuador', '{6}', 'Agua Potable para 500 Familias', 'Inauguramos el sistema de filtración comunitaria. Se acabaron las enfermedades gastrointestinales.', '{"https://images.unsplash.com/photo-1538300342682-cf57afb97285?auto=format&fit=crop&w=800&q=80"}', 540, 34),
(109, 'd0000000-0000-0000-0000-000000000000', 'Global', '{17}', 'Buscando Alianzas Estratégicas', 'Para escalar nuestro impacto en LATAM, necesitamos conectar con ONGs locales que ya tengan trabajo de campo.', '{}', 150, 28),
(110, 'd1111111-1111-1111-1111-111111111111', 'Bogotá, Colombia', '{15}', 'Jornada de Reforestación: Resultados', 'Plantamos 300 árboles nativos en el cerro oriental. En 5 años, esto será un bosque.', '{"https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=800&q=80"}', 410, 38)
