-- DATA MIGRATION SCRIPT (FULL)

-- 1. MOCK PROFILES (Deterministic UUIDs from email/names)
ON CONFLICT (id) DO UPDATE SET (name, role, avatar, bio) = (EXCLUDED.name, EXCLUDED.role, EXCLUDED.avatar, EXCLUDED.bio);

-- 2. PROJECTS (Full Sync)
ON CONFLICT (id) DO UPDATE SET (title, description, progress) = (EXCLUDED.title, EXCLUDED.description, EXCLUDED.progress);

-- 3. POSTS (Full Sync)
ON CONFLICT (id) DO UPDATE SET (title, content, likes_count) = (EXCLUDED.title, EXCLUDED.content, EXCLUDED.likes_count);
